(* UCodeInit.v -- the CODE CATALOG of the user program [init].
   AUTO-GENERATED by tools/gen_ucode.py.  DO NOT EDIT BY HAND.

   The verified-user tier (claude-notes/projects/user-verified.md) drives
   one step from one [uinstr] fact (UmodeMem.v): the pure statement that at
   a given user pc the program's bytes sit in the process image [M], the
   pc's page is mapped fetch-executable, and the fetched word decodes to a
   named AST on any U-mode machine. This file proves those facts for the
   369 instruction(s) of this catalog, from the dumped image
   [User.InitInstrs.init_bytes].

   Two premises carry every [uinstr] lemma:

     [init_text_sub M]   -- [M] contains the dumped text (so a proof may talk
                          about a process image that ALSO has rodata, bss, a
                          stack page and an argument area in it);
     [init_text_layout pt]
                       -- the pure page-table fact: each of the 1 page(s) of
                          the executable segment (0x0 .. 0xfff) is mapped with a
                          leaf that permits instruction FETCH and a user data
                          LOAD.  The load half is not decoration: a program's
                          .rodata shares a text page and its string literals are
                          handed to [write]/[exec] as buffers.  The DATA page and
                          the heap are NOT this file's business -- they are
                          read-WRITE and belong to USpecInit.v, as do the stack and
                          argv facts.

   Image geometry, as dumped:
     text  0x0 .. 0x96c   (2412 bytes)
     PT_LOAD 0x0      filesz 0xe6c    memsz 0xe6c    flags 5   (executable: 1 text page(s))
     PT_LOAD 0x1000   filesz 0x10     memsz 0x30     flags 6
     data  0x96c .. 0x1010   (1296 bytes)
     entry 0xbc, MemBase 0x0, MemEnd 0x1030

   Catalogued: 369 instruction(s), 246 distinct word(s), in 13 function(s):
     <start>          0xbc     .. 0xc8         6 instr
     <main>           0x0      .. 0xb8        57 instr
     <printf>         0x7c0    .. 0x7f0       20 instr
     <vprintf>        0x4d6    .. 0x794      250 instr
     <putc>           0x41a    .. 0x436       12 instr
     <open>           0x3b2    .. 0x3b8        3 instr
     <mknod>          0x3ba    .. 0x3c0        3 instr
     <dup>            0x3ea    .. 0x3f0        3 instr
     <fork>           0x36a    .. 0x370        3 instr
     <wait>           0x37a    .. 0x380        3 instr
     <exec>           0x3aa    .. 0x3b0        3 instr
     <write>          0x392    .. 0x398        3 instr
     <exit>           0x372    .. 0x378        3 instr

   NOT catalogued, because no proof ever fetches it:
       atoi, chdir, close, fstat, getpid, gets, kill, link, memcmp, memcpy,
       memmove, memset, mkdir, pause, pipe, read, stat, strchr, strcmp, strcpy,
       strlen, sync, unlink, uptime -- library or syscall stub that init never
       calls
       free, malloc, sbrk, sbrklazy, sys_sbrk -- unreachable: init allocates
       nothing
       fprintf -- unreachable: init calls printf, never fprintf
       printint -- unreachable: vprintf reaches it only from a state == '%'
       arm, and none of init's four format strings contains a '%'

   This catalog covers init as it runs: the console-priming prologue, the
   restart loop around fork/exec/wait, and the printf cone underneath the
   four diagnostics. Its coverage claim is the list of omitted functions
   above, not all of ulib.

   Every AST below was READ OFF the model -- [vm_compute] of the decoder at
   the U-mode reference state [dstateU] (base) / [decode_c_pure] under the
   misa.C gate (compressed) -- never guessed. In particular every
   jal/branch immediate is the decoder's POSITIVE residue, and a COMPRESSED
   branch or jump immediate counts HALFwords. The compressed words decode
   to the raw C_* constructors -- the expansion into ITYPE/STORE/...
   happens in [execute], not here.
 *)
