(* ===================================================================== *)
(* §0 The image and the layout premise.                                   *)
(* ===================================================================== *)

(* [M] contains the dumped text -- the generic image inclusion (UmodeAbi.v)
   at this program's text bytes.  An inclusion (not an equality), so a
   process image carrying rodata/bss/stack/argv on top still qualifies. *)
Definition init_text_sub (M : gmap Z (bv 8)) : Prop :=
  uimg_sub InitInstrs.init_bytes M.

(* ... and the dumped RODATA/data.  A string literal a program hands to
   [write] lives here, not in the text map, so the readable-window lemma
   below needs THIS inclusion. *)
Definition init_data_sub (M : gmap Z (bv 8)) : Prop :=
  uimg_sub InitData.init_data M.

(* ... and the two together, so a spec carries ONE image premise.  The
   per-pc [uinstr] facts below deliberately take only [init_text_sub]: an
   instruction fetch never reads the data half. *)
Definition init_img_sub (M : gmap Z (bv 8)) : Prop :=
  init_text_sub M /\ init_data_sub M.

Lemma init_img_text (M : gmap Z (bv 8)) : init_img_sub M -> init_text_sub M.
Proof. intros [ H _ ]. exact H. Qed.
Lemma init_img_data (M : gmap Z (bv 8)) : init_img_sub M -> init_data_sub M.
Proof. intros [ _ H ]. exact H. Qed.

(* ---- the KEY RANGE of each dumped map ------------------------------- *)
(* The bounds are COMPUTED from the dump (text keys stop at 0x96b, data keys
   at 0x100f) and rounded up to the next page, which is the shape the users of
   the fact want: [UmodeAbi.uM_only_img] asks exactly "the written window is
   disjoint from every key of [img]", and the windows a program writes are
   its stack, which starts at a page boundary above the image. *)

Lemma list_key_lt {A : Type} (L : list (Z * A)) (B k : Z) (b : A) :
  forallb (fun kv => Z.ltb (fst kv) B) L = true -> In (k, b) L -> k < B.
Proof.
  induction L as [ | x xs IH ]; cbn [forallb In]; [ tauto | ].
  intros HF [ Hx | Hin ].
  - apply andb_prop in HF as [ H1 _ ]. subst x. cbn in H1.
    apply Z.ltb_lt in H1. exact H1.
  - apply andb_prop in HF as [ _ H2 ]. exact (IH H2 Hin).
Qed.

(* ...and the LOWER bound, which the same [forallb] decides.  [Hx] and
   every other page-range hypothesis is two-sided, so a key fact that
   only bounds above leaves [0 <= k] for [lia] to invent out of nothing. *)
Lemma list_key_nonneg {A : Type} (L : list (Z * A)) (k : Z) (b : A) :
  forallb (fun kv => Z.leb 0 (fst kv)) L = true -> In (k, b) L -> 0 <= k.
Proof.
  induction L as [ | x xs IH ]; cbn [forallb In]; [ tauto | ].
  intros HF [ Hx | Hin ].
  - apply andb_prop in HF as [ H1 _ ]. subst x. cbn in H1.
    apply Z.leb_le in H1. exact H1.
  - apply andb_prop in HF as [ _ H2 ]. exact (IH H2 Hin).
Qed.

Lemma init_bytes_key_lt (k : Z) (b : bv 8) :
  InitInstrs.init_bytes !! k = Some b -> k < 4096.
Proof.
  intro Hk.
  apply elem_of_list_to_map_2 in Hk.
  apply elem_of_list_In in Hk.
  refine (list_key_lt _ 4096 k b _ Hk).
  vm_compute. reflexivity.
Qed.

Lemma init_bytes_key_nonneg (k : Z) (b : bv 8) :
  InitInstrs.init_bytes !! k = Some b -> 0 <= k.
Proof.
  intro Hk.
  apply elem_of_list_to_map_2 in Hk.
  apply elem_of_list_In in Hk.
  refine (list_key_nonneg _ k b _ Hk).
  vm_compute. reflexivity.
Qed.

Lemma init_data_key_lt (k : Z) (b : bv 8) :
  InitData.init_data !! k = Some b -> k < 8192.
Proof.
  intro Hk.
  apply elem_of_list_to_map_2 in Hk.
  apply elem_of_list_In in Hk.
  refine (list_key_lt _ 8192 k b _ Hk).
  vm_compute. reflexivity.
Qed.

Lemma init_data_key_nonneg (k : Z) (b : bv 8) :
  InitData.init_data !! k = Some b -> 0 <= k.
Proof.
  intro Hk.
  apply elem_of_list_to_map_2 in Hk.
  apply elem_of_list_In in Hk.
  refine (list_key_nonneg _ k b _ Hk).
  vm_compute. reflexivity.
Qed.

(* The vpn of an address IS the vpn of its page base.  This is the
   arithmetic the two projections below need, and having it ONCE is what
   lets a per-pc proof state no svpn identity of its own -- UCodeEcho.v
   could do that identification with a [vm_compute] per instance only
   because its whole image was page 0. *)
Lemma init_svpn_page (a : Z) :
  0 <= a < 274877906944 ->
  svpn_of (mword_of_int a : mword 64)
    = svpn_of (mword_of_int (4096 * (a / 4096)) : mword 64).
Proof.
  intros [ Hlo Hhi ].
  assert (Hq : 0 <= 4096 * (a / 4096) <= a).
  { split.
    - apply Z.mul_nonneg_nonneg; [ lia | apply Z.div_pos; lia ].
    - apply Z.mul_div_le; lia. }
  apply bv_eq.
  rewrite (svpn_of_unsigned_lo (mword_of_int a : mword 64))
    by (rewrite uint_unsigned, moi64_small; lia).
  rewrite (svpn_of_unsigned_lo (mword_of_int (4096 * (a / 4096)) : mword 64))
    by (rewrite uint_unsigned, moi64_small; lia).
  rewrite !uint_unsigned, !moi64_small by lia.
  rewrite !Z.shiftr_div_pow2 by lia.
  change (2 ^ 12) with 4096.
  rewrite (Z.mul_comm 4096 (a / 4096)), Z.div_mul by lia. reflexivity.
Qed.

(* The pure page-table premise: each of the 1 page(s) of the executable
   segment is mapped with a leaf that permits instruction FETCH and a user
   data LOAD.  Quantified over the page INDEX rather than one field per
   page, so the record does not change shape when a program grows; page [i]
   is user va [4096*i], because a user program is linked at 0
   (user/user.ld).  The load half is what makes a .rodata string sharing a
   text page a legal [write] buffer. *)
Record init_text_layout (pt : uptd) : Prop := InitTextLayout {
  itl_pg : forall i : Z, 0 <= i < 1 ->
    exists w : mword 64,
      ud_um pt !! svpn_of (mword_of_int (4096 * i) : mword 64) = Some w /\
      uleaf_ok (InstructionFetch tt) w /\ uleaf_ok (Load Data) w
}.

(* the fetch projection, in exactly the shape [UmodeMem.uva_fetch_leaf]
   wants -- it takes the page index from the address itself *)
Lemma init_text_layout_fetch (pt : uptd) (off : Z) :
  init_text_layout pt -> 0 <= off < 4096 ->
  uva_fetch_leaf pt (mword_of_int off).
Proof.
  intros [ Hpg ] Hoff.
  destruct (Hpg (off / 4096)
              ltac:(split; [ apply Z.div_pos; lia
                           | apply Z.div_lt_upper_bound; lia ]))
    as (w & Hl & Hok & _).
  exists w. rewrite (init_svpn_page off ltac:(lia)). split; assumption.
Qed.

(* the same leaf, in the shape [UmodeAbi.uv_rd]'s [urd_leaf] field wants *)
Lemma init_text_layout_load (pt : uptd) (a : Z) :
  init_text_layout pt -> 0 <= a < 4096 ->
  exists w : mword 64,
    ud_um pt !! svpn_of (mword_of_int a : mword 64) = Some w /\
    uleaf_ok (Load Data) w.
Proof.
  intros [ Hpg ] Ha.
  destruct (Hpg (a / 4096)
              ltac:(split; [ apply Z.div_pos; lia
                           | apply Z.div_lt_upper_bound; lia ]))
    as (w & Hl & _ & Hok).
  exists w. rewrite (init_svpn_page a ltac:(lia)). split; assumption.
Qed.

(* ONE readable byte of the loaded data image, on a text page -- the
   address is a parameter, so each string literal a program hands to
   [write] costs one line at the call site. *)
Lemma init_rodata_rd1 (pt : uptd) (M : gmap Z (bv 8)) (a : Z) (b : bv 8) :
  init_text_layout pt -> init_data_sub M ->
  0 <= a < 4096 ->
  InitData.init_data !! a = Some b ->
  uv_rd pt M a 1.
Proof.
  intros Hl Hsub Ha Hb. constructor.
  - lia.
  - lia.
  - change (2 ^ 38) with 274877906944. lia.
  - intros j Hj. assert (Hj0 : j = 0) by lia. subst j.
    rewrite Z.add_0_r. exact (init_text_layout_load pt a Hl Ha).
  - intros j Hj. assert (Hj0 : j = 0) by lia. subst j.
    rewrite Z.add_0_r. exists b. exact (Hsub a b Hb).
Qed.

(* the addresses this file is about, as the dumper named them *)
Lemma init_syms_pins :
  InitSyms.start = 0xbc /\
  InitSyms.main = 0x0 /\
  InitSyms.printf = 0x7c0 /\
  InitSyms.vprintf = 0x4d6 /\
  InitSyms.putc = 0x41a /\
  InitSyms.open = 0x3b2 /\
  InitSyms.mknod = 0x3ba /\
  InitSyms.dup = 0x3ea /\
  InitSyms.fork = 0x36a /\
  InitSyms.wait = 0x37a /\
  InitSyms.exec = 0x3aa /\
  InitSyms.write = 0x392 /\
  InitSyms.exit = 0x372.
Proof.
  unfold InitSyms.start,
         InitSyms.main,
         InitSyms.printf,
         InitSyms.vprintf,
         InitSyms.putc,
         InitSyms.open,
         InitSyms.mknod,
         InitSyms.dup,
         InitSyms.fork,
         InitSyms.wait,
         InitSyms.exec,
         InitSyms.write,
         InitSyms.exit.
  split_and!; reflexivity.
Qed.

(* ===================================================================== *)
(* §1 Per-WORD decode facts.                                              *)
(* ===================================================================== *)

(* One lemma per DISTINCT word (246 of them for 369 instructions), reused
   at every pc where that word occurs.

   Base words: the concrete-state bridge at [dstateU] (WpDecodeBridge),
   transported to any state agreeing with it on the U-mode decode read set
   [D_u] -- exactly the [udecode_base] shape [uinstr] wants. The closing
   step descends the AST with [f_equal] and finishes each bitvector leaf
   with [bv_eq] (a bare [reflexivity] would have to match well-formedness
   proof terms).

   Compressed words: [rvc_oneshot] under the misa.C premise. *)

Ltac udec_base_bridge :=
  let s := fresh "s" in let Hag := fresh "Hag" in
  intros s Hag;
  apply (decode_state_bridge D_u _ dstateU);
  [ exact Hag
  | vm_compute; reflexivity
  | vm_compute; repeat first [ reflexivity | (apply bv_eq; vm_compute; reflexivity) | f_equal ] ].

Ltac udec_rvc_oneshot :=
  let s := fresh "s" in let Hm := fresh "Hm" in intros s Hm; rvc_oneshot s Hm.

